+++ /workspace/task_env/rwlock_try_upread_verified.rs	2026-09-01 19:55:02.841025284 +0000
@@ -2822,10 +2822,13 @@
         proof_decl!{
             let tracked mut upgrade_guard_token: Option<OneLeftOwner<HalfPerm<T>, NoPerm<T>, 3>> = None;
             let tracked mut retract_upgrade_token: Option<UniqueToken> = None;
+            let ghost mut failed_writer = false;
+            let ghost mut first_prev = 0usize;
         }
         proof!{
             use_type_invariant(self);
             lemma_consts_properties();
+            reveal(RwLock::wf);
         }
         let guard = G::guard();
         let lock =
@@ -2833,6 +2836,21 @@
             self.lock => fetch_or(UPGRADEABLE_READER);
             update prev -> next;
             ghost g => {
+                lemma_consts_properties_prev_next(prev, next);
+                lemma_consts_properties_value(prev);
+                first_prev = prev;
+                if next & (WRITER | UPGRADEABLE_READER) == 0 {
+                    assert(prev & (WRITER | UPGRADEABLE_READER) == 0) by (bit_vector);
+                    assert(!g.core_token.is_right());
+                    assert(g.upread_retract_token is Some);
+                    assert(g.upreader_guard_token is Some);
+                    upgrade_guard_token = Some(g.upreader_guard_token.tracked_take());
+                } else if next & (WRITER | UPGRADEABLE_READER) == WRITER {
+                    assert(prev & WRITER != 0) by (bit_vector);
+                    failed_writer = true;
+                    assert(g.upread_retract_token is Some);
+                    retract_upgrade_token = Some(g.upread_retract_token.tracked_take());
+                }
             }
         )
             & (WRITER | UPGRADEABLE_READER);
@@ -2845,10 +2863,25 @@
                 },
             );
         } else if lock == WRITER {
+            proof {
+                lemma_consts_properties();
+                assert((lock as usize) == WRITER);
+                assert((lock as usize) & UPGRADEABLE_READER == 0);
+            }
             atomic_with_ghost!(
                 self.lock => fetch_sub(UPGRADEABLE_READER);
                 update prev -> next;
                 ghost g => {
+                    assert((first_prev as usize) & (WRITER | UPGRADEABLE_READER) == WRITER);
+                    lemma_consts_properties_prev_next(prev as usize, next as usize);
+                    lemma_consts_properties_value(prev as usize);
+                    if failed_writer {
+                        let tracked token = match retract_upgrade_token {
+                            Some(token) => token,
+                            None => proof_from_false(),
+                        };
+                        g.upread_retract_token = Some(token);
+                    }
                 }
             );
         }
